import type { TradingAgent } from './types.js';

export const multi: TradingAgent = {
  id: 'multi',
  async run(task, tools) {
    const symbol = task.intent.symbol;
    const results = await tools.searchTokens(symbol);
    const top = results[0], label = symbol;
    let usd = task.intent.usd; let addr = top.address;
    const quote = await tools.getQuote(addr, usd);
    await tools.buy(top.address, usd, quote.tokensOut * 0.99, label);
  },
};
